export function setupPartyUI({create=()=>{},join=()=>{},team=()=>{},ready=()=>{},start=()=>{},configure=()=>{},leave=()=>{}},root=document){const node=id=>root.getElementById(id);let current=null;
 node('party-create').addEventListener('click',()=>create({maxPeople:Number(node('party-size').value),duration:Number(node('party-time').value)*60}));node('party-join-form').addEventListener('submit',event=>{event.preventDefault();join(node('party-invite-input').value);});node('party-team').addEventListener('change',()=>team(node('party-team').value==='spectate'?null:Number(node('party-team').value)));node('party-ready').addEventListener('click',()=>ready(!current?.self?.ready));node('party-start').addEventListener('click',start);node('party-configure').addEventListener('click',()=>configure({maxPeople:Number(node('party-live-size').value),duration:Number(node('party-live-time').value)*60}));node('party-leave').addEventListener('click',leave);node('party-dialog').addEventListener('cancel',event=>{event.preventDefault();leave();});node('party-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(current.code);node('party-status').textContent='Invite copied. Send it to your friends.';}catch{node('party-code').focus();node('party-code').select();node('party-status').textContent='Copy the selected invite code and send it to your friends.';}});
 function render(room,error=''){current=room;const active=!!room&&!room.closed,host=room?.role==='host',self=room?.self;node('party-setup').hidden=active;node('party-lobby').hidden=!active;node('party-status').textContent=error||room?.error||room?.notice||(room?.status==='connecting'?'Connecting to the lobby…':room?.status==='starting'?'Preparing all selected vehicles. Please wait…':active?'Choose Blue, Orange or Spectate, then select Ready. The host starts the match.':'Host a custom lobby or enter its BC2 invite.');if(!active)return;node('party-code').value=room.code||'';node('party-code').readOnly=true;node('party-copy').disabled=!room.code;node('party-team').value=self?.team===null?'spectate':String(self?.team??'spectate');const playing=!!room.preparing||!!room.pendingMatch||!!room.matchId&&room.sim?.phase!=='ended';node('party-team').disabled=playing;node('party-ready').disabled=!self||self.team===null||playing;node('party-ready').textContent=self?.team===null?'SPECTATING':self?.ready?'READY ✓ · CLICK TO UNREADY':'READY';node('party-start').hidden=!host;node('party-start').disabled=room.status==='starting'||!room.members.some(member=>member.team!==null)||room.members.some(member=>member.team!==null&&(!member.connected||!member.ready||room.sim?.phase==='ended'&&!member.rematch));node('party-start').textContent=room.matchId?'START NEW MATCH':'START MATCH';node('party-settings').hidden=!host;node('party-live-size').value=String(room.options.maxPeople);node('party-live-time').value=String(room.options.duration/60);node('party-configure').disabled=playing;node('party-live-size').disabled=playing;node('party-live-time').disabled=playing;
  const roster=node('party-roster');roster.replaceChildren();for(const member of room.members){const row=root.createElement('div'),name=root.createElement('strong'),details=root.createElement('span');row.className='party-member';name.textContent=(member.look?.name||member.name||'Driver')+(member.id===room.id?' · YOU':'')+(member.id===0?' · HOST':'');details.textContent=(member.team===null?'SPECTATOR':member.team===0?'BLUE':'ORANGE')+' · '+(!member.connected?'RECONNECTING':member.ready?'READY':'NOT READY');row.append(name,details);roster.append(row);}node('party-count').textContent=room.members.length+' / '+room.options.maxPeople+' PEOPLE · '+room.options.duration/60+' MINUTES';
 }
 return {render,open(){if(!node('party-dialog').open)node('party-dialog').showModal();}};
}
